9	// These tests pin credential redaction for a schemeless upstream — an
10	// address written with a leading "//" and no scheme, e.g.
11	// "//alice:pw%4@api.internal/v1". Such an upstream is always rejected
12	// (never promoted to http or https), but its failure diagnostic must hide
13	// the whole username and optional password exactly like a scheme-bearing
14	// address: the address may only appear as "//***@host/...", the '@', host,
15	// port and base path are kept, and neither the original nor the decoded
16	// credential bytes may appear anywhere in the reason. A malformed escape in
17	// the userinfo is reported as a userinfo problem without quoting the bad
18	// fragment; a bad host or base path keeps its own diagnostic and its
19	// fragment, and the existing error-selection order is unchanged.
20	
21	// schemelessRedactionCase is one upstream and the exact redacted address
22	// the reason must quote, alongside bytes that must never appear.
23	type schemelessRedactionCase struct {
24		name     string
25		upstream string
26		shown    string
27		hidden   []string
28	}
29	
30	func schemelessConfig(upstream string) string {
31		return `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + upstream + `"}]}`
32	}
33	
34	// assertSchemelessRejected parses the one-route config, requires
35	// invalid_config with no config handed back, a route/id/upstream-located
36	// reason that never calls the legal JSON broken, and (when shown is set)
37	// the redacted address quoted in the reason with none of the hidden bytes.
38	func assertSchemelessRejected(t *testing.T, src, shown string, hidden []string) *Failure {
39		t.Helper()
40		cfg, f := ParseConfig([]byte(src))
41		if f == nil || f.Code != "invalid_config" {
42			t.Fatalf("got cfg=%+v f=%+v, want invalid_config", cfg, f)
43		}
44		if cfg != nil {
45			t.Fatalf("a rejected config must not be returned, got %+v", cfg)
46		}
47		for _, want := range []string{"route 1", `"api"`, "upstream"} {
48			if !strings.Contains(f.Reason, want) {
49				t.Fatalf("reason = %q, want substring %q", f.Reason, want)
50			}
51		}
52		if strings.Contains(f.Reason, "not valid JSON") {
53			t.Fatalf("a schemeless upstream is a content error, not a JSON syntax failure: %q", f.Reason)
54		}
55		if shown != "" {
56			if !strings.Contains(f.Reason, `"`+shown+`"`) {
57				t.Fatalf("reason = %q, want the redacted address %q quoted", f.Reason, shown)
58			}
59		}
60		for _, leaked := range hidden {
61			if strings.Contains(f.Reason, leaked) {
62				t.Fatalf("reason = %q leaks credential %q", f.Reason, leaked)
63			}
64		}
65		return f
66	}
67	
68	// TestSchemelessUpstreamHeadlineRedaction drives the headline case:
69	// //alice:pw%4@api.internal/v1 fails the userinfo-escape content rule and
70	// must be shown only as //***@api.internal/v1.
71	func TestSchemelessUpstreamHeadlineRedaction(t *testing.T) {
72		src := schemelessConfig("//alice:pw%4@api.internal/v1")
73		f := assertSchemelessRejected(t, src, "//***@api.internal/v1",
74			[]string{"alice", "pw%4", "p@", `"%4"`, "//alice"})
75		for _, want := range []string{"invalid percent escape in its userinfo"} {
76			if !strings.Contains(f.Reason, want) {
77				t.Fatalf("reason = %q, want substring %q", f.Reason, want)
78			}
79		}
80	}
81	
82	// TestSchemelessUpstreamBadUserinfoEscapeDedicatedReason covers every
83	// malformed-credential shape: truncated and lone escapes, a bad username
84	// (with and without a password) and an empty password. The fixed reason
85	// names the userinfo and never quotes the offending fragment.
86	func TestSchemelessUpstreamBadUserinfoEscapeDedicatedReason(t *testing.T) {
87		cases := []schemelessRedactionCase{
88			{"illegal escape in password", "//alice:%zz@host.internal/base", "//***@host.internal/base", []string{"alice", "%zz", `"%zz"`}},
89			{"truncated escape at password end", "//alice:pw%2@host.internal/base", "//***@host.internal/base", []string{"alice", "pw%2", `"%2"`}},
90			{"truncated escape mid password", "//alice:p%4@host.internal/", "//***@host.internal/", []string{"alice", "p%4", `"%4"`}},
91			{"lone percent in password", "//alice:pw%@host/", "//***@host/", []string{"alice", "pw%", `"%"`}},
92			{"illegal escape in username with password", "//%zz:secret@host.internal/base", "//***@host.internal/base", []string{"secret", "%zz", `"%zz"`}},
93			{"illegal escape in username only", "//al%zz@host.internal/base", "//***@host.internal/base", []string{"al%zz", `"%zz"`}},
94			{"username only truncated escape", "//u%4@host/base", "//***@host/base", []string{"u%4", `"%4"`}},
95			{"empty password then bad username", "//%zz:@host/", "//***@host/", []string{"%zz", `"%zz"`}},
96			{"credential also carries an at sign text", "//al@ice:pw%4@host.internal/v1", "//***@host.internal/v1", []string{"al@ice", "pw%4"}},
97			{"at sign in base path is not userinfo", "//alice:pw%4@host.internal/v1@x", "//***@host.internal/v1@x", []string{"alice", "pw%4"}},
98		}
99		for _, tc := range cases {
100			t.Run(tc.name, func(t *testing.T) {
101				f := assertSchemelessRejected(t, schemelessConfig(tc.upstream), tc.shown, tc.hidden)
102				if !strings.Contains(f.Reason, "invalid percent escape in its userinfo") {
103					t.Fatalf("reason = %q, want the dedicated userinfo reason", f.Reason)
104				}
105			})
106		}
107	}
108	
109	// TestSchemelessUpstreamLegalUserinfoStillRejectedSilently pins that a
110	// schemeless address with perfectly legal credentials is rejected for the
111	// missing scheme and the reason neither quotes the address (so it cannot
112	// leak the credentials) nor gains an http/https prefix.
113	func TestSchemelessUpstreamLegalUserinfoStillRejectedSilently(t *testing.T) {
114		cases := []struct {
115			name     string
116			upstream string
117			hidden   []string
118		}{
119			{"host and base path", "//alice:p%40ss@api.internal/v1", []string{"alice", "p%40ss", "p@ss"}},
120			{"username only", "//alice@host.internal/base", []string{"alice"}},
121			{"empty password", "//alice:@host.internal/base", []string{"alice"}},
122			{"no userinfo", "//api.internal/v1", nil},
123			{"bracketed ipv6 host", "//[2001:db8::1]/v1", nil},
124			{"port and path", "//host.internal:8080/base", nil},
125		}
126		for _, tc := range cases {
127			t.Run(tc.name, func(t *testing.T) {
128				f := assertSchemelessRejected(t, schemelessConfig(tc.upstream), "", tc.hidden)
129				if !strings.Contains(f.Reason, "upstream must be an absolute http or https URL") {
130					t.Fatalf("reason = %q, want the absolute http/https rule", f.Reason)
131				}
132				// Redaction must never invent a scheme.
133				for _, leaked := range []string{"http://", "https://", "HTTP://", "HTTPS://"} {
134					if strings.Contains(f.Reason, leaked) {
135						t.Fatalf("reason = %q must not add a scheme", f.Reason)
136					}
137				}
138			})
139		}
140	}
141	
142	// TestSchemelessUpstreamHostAndPathDiagnosticsKept pins the redaction
143	// boundary: with legal credentials, a malformed escape that belongs to the
144	// host or base path keeps its own diagnostic and its fragment (so it is not
145	// mislabeled a password problem), while only the credentials are hidden. An
146	// '@' inside the base path stays a path character and never widens the
147	// hidden range.
148	func TestSchemelessUpstreamHostAndPathDiagnosticsKept(t *testing.T) {
149		cases := []struct {
150			name     string
151			upstream string
152			shown    string
153			keep     []string
154			hidden   []string
155		}{
156			{
157				name:     "illegal escape in base path with legal userinfo",
158				upstream: "//alice:p%40ss@api.internal/%zz",
159				shown:    "//***@api.internal/%zz",
160				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`},
161				hidden:   []string{"alice", "p%40ss", "p@ss"},
162			},
163			{
164				name:     "illegal escape in host with legal userinfo",
165				upstream: "//alice:secret@ho%zzst/",
166				shown:    "//***@ho%zzst/",
167				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`},
168				hidden:   []string{"alice", "secret"},
169			},
170			{
171				name:     "at sign in base path is path content",
172				upstream: "//alice:pw9@host.internal/v1@x%zz",
173				shown:    "//***@host.internal/v1@x%zz",
174				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`, "/v1@x%zz"},
175				hidden:   []string{"alice", "pw9"},
176			},
177			{
178				name:     "illegal escape in host without userinfo stays whole",
179				upstream: "//ho%zzst/",
180				shown:    "//ho%zzst/",
181				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`},
182				hidden:   nil,
183			},
184			{
185				name:     "illegal escape in base path without userinfo stays whole",
186				upstream: "//host.internal/base%zz/x",
187				shown:    "//host.internal/base%zz/x",
188				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`},
189				hidden:   nil,
190			},
191			{
192				name:     "bad userinfo and host escapes together report the host first",
193				upstream: "//alice:pw%4@ho%zzst/",
194				shown:    "//***@ho%zzst/",
195				keep:     []string{"not a valid URL", `invalid URL escape "%zz"`},
196				hidden:   []string{"alice", "pw%4", `"%4"`},
197			},
198		}
199		for _, tc := range cases {
200			t.Run(tc.name, func(t *testing.T) {
201				f := assertSchemelessRejected(t, schemelessConfig(tc.upstream), tc.shown, tc.hidden)
202				for _, want := range tc.keep {
203					if !strings.Contains(f.Reason, want) {
204						t.Fatalf("reason = %q, want host/path diagnostic %q preserved", f.Reason, want)
205					}
206				}
207				if strings.Contains(f.Reason, "invalid percent escape in its userinfo") {
208					t.Fatalf("reason = %q must not mislabel a host/path error as a userinfo error", f.Reason)
209				}
210			})
211		}
212	}
213	
214	// TestSchemelessUpstreamHostValidatorsRedactUserinfo pins that the raw
215	// host validators — which now run for a schemeless "//" address too —
216	// each keep their own wording while any userinfo is hidden whole.
217	func TestSchemelessUpstreamHostValidatorsRedactUserinfo(t *testing.T) {
218		cases := []struct {
219			name     string
220			upstream string
221			shown    string
222			want     string
223			hidden   []string
224		}{
225			{
226				name:     "missing host after userinfo",
227				upstream: "//alice:s3cr%40t@:8443/v1",
228				shown:    "//***@:8443/v1",
229				want:     "missing a host",
230				hidden:   []string{"alice", "s3cr%40t"},
231			},
232			{
233				name:     "userinfo reduced to empty authority",
234				upstream: "//svc@/base",
235				shown:    "//***@/base",
236				want:     "missing a host",
237				hidden:   []string{"svc"},
238			},
239			{
240				name:     "extra colon in host part after userinfo",
241				upstream: "//alice:s3:cr3t@api:internal:8080/base",
242				shown:    "//***@api:internal:8080/base",
243				want:     "more than one colon",
244				hidden:   []string{"alice", "s3:cr3t"},
245			},
246			{
247				name:     "bracketed host is not an ipv6 literal",
248				upstream: "//alice:secret@[not-an-ip]/x",
249				shown:    "", // this reason quotes only the literal, not the address
250				want:     "not a legal IPv6 address",
251				hidden:   []string{"alice", "secret"},
252			},
253			{
254				name:     "unbracketed ipv6 host missing brackets",
255				upstream: "//alice:secret@2001:db8::1/",
256				shown:    "",
257				want:     "missing its square brackets",
258				hidden:   []string{"alice", "secret"},
259			},
260			{
261				name:     "port out of range",
262				upstream: "//alice:x@h:99999/x",
263				shown:    "",
264				want:     "out of range",
265				hidden:   []string{"alice"},
266			},
267			{
268				name:     "direct space in base path",
269				upstream: "//alice:x@h/base path",
270				shown:    "",
271				want:     "unencoded space",
272				hidden:   []string{"alice"},
273			},
274		}
275		for _, tc := range cases {
276			t.Run(tc.name, func(t *testing.T) {
277				f := assertSchemelessRejected(t, schemelessConfig(tc.upstream), tc.shown, tc.hidden)
278				if !strings.Contains(f.Reason, tc.want) {
279					t.Fatalf("reason = %q, want the %q diagnostic", f.Reason, tc.want)
280				}
281				if tc.shown != "" {
282					// The address-quoting validators must hide the credentials;
283					// reasons above that quote only a host fragment (bracketed
284					// host, IPv6 literal, port, space) carry no address at all.
285				}
286			})
287		}
288	}
289	
290	// TestSchemelessUpstreamErrorSelectionOrderUnchanged pins that hiding
291	// credentials never changes which error is reported when the userinfo and
292	// the host or base path are both wrong: the host-shape and base-path rules
293	// keep preceding the url.Parse userinfo-escape attribution, exactly as for
294	// a scheme-bearing address.
295	func TestSchemelessUpstreamErrorSelectionOrderUnchanged(t *testing.T) {
296		cases := []struct {
297			name     string
298			upstream string
299			want     string
300			hidden   []string
301		}{
302			{"bad bracket beats bad userinfo escape", "//alice:%zz@[not-an-ip]/x", "not a legal IPv6 address", []string{"alice", "%zz"}},
303			{"out of range port beats bad userinfo escape", "//alice:%zz@h:99999/x", "out of range", []string{"alice", "%zz"}},
304			{"missing host beats bad userinfo escape", "//alice:%zz@:8080/x", "missing a host", []string{"alice", "%zz"}},
305			{"base path space beats bad userinfo escape", "//alice:%zz@h/base path", "unencoded space", []string{"alice", "%zz"}},
306		}
307		for _, tc := range cases {
308			t.Run(tc.name, func(t *testing.T) {
309				f := assertSchemelessRejected(t, schemelessConfig(tc.upstream), "", tc.hidden)
310				if !strings.Contains(f.Reason, tc.want) {
311					t.Fatalf("reason = %q, want the earlier %q diagnostic", f.Reason, tc.want)
312				}
313			})
314		}
315	}
316	
317	// TestSchemelessUpstreamRejectsWholeConfig pins that a schemeless upstream
318	// on a later route rejects the whole configuration even when the request
319	// only matches a different, legal route, and the reason locates the
320	// offending route by its 1-based position and id with the credentials
321	// hidden.
322	func TestSchemelessUpstreamRejectsWholeConfig(t *testing.T) {
323		src := `{"routes":[
324		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
325		  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"//alice:pw%4@api.internal/v1"}
326		]}`
327		cfg, f := ParseConfig([]byte(src))
328		if f == nil || f.Code != "invalid_config" {
329			t.Fatalf("got cfg=%+v f=%+v, want invalid_config", cfg, f)
330		}
331		if cfg != nil {
332			t.Fatalf("the whole config must be rejected even though /api only hits route 1, got %+v", cfg)
333		}
334		for _, want := range []string{"route 2", `"admin"`, "upstream", "invalid percent escape in its userinfo", `"//***@api.internal/v1"`} {
335			if !strings.Contains(f.Reason, want) {
336				t.Fatalf("reason = %q, want substring %q", f.Reason, want)
337			}
338		}
339		for _, leaked := range []string{"alice", "pw%4", `"%4"`} {
340			if strings.Contains(f.Reason, leaked) {
341				t.Fatalf("reason = %q leaks %q", f.Reason, leaked)
342			}
343		}
344	}
345	
346	// TestSchemelessUpstreamRejectedAfterSaveRoundTrip pins that the read
347	// interface is the gate a schemeless upstream cannot pass even after a
348	// save/re-read cycle: a marshalled document carrying one is rejected on
349	// re-parse with the same redacted diagnostic, while a legal https upstream
350	// with userinfo still round-trips with its credentials byte for byte.
351	func TestSchemelessUpstreamRejectedAfterSaveRoundTrip(t *testing.T) {
352		bypassed := &Config{Routes: []Route{{
353			ID: "r", Methods: []string{"GET"}, PathPrefix: "/", Upstream: "//alice:pw%4@host.internal/v1",
354		}}}
355		saved, err := json.Marshal(bypassed)
356		if err != nil {
357			t.Fatalf("marshal: %v", err)
358		}
359		if !strings.Contains(string(saved), "//alice:pw%4@host.internal/v1") {
360			t.Fatalf("save keeps the configured bytes verbatim: %s", saved)
361		}
362		cfg, f := ParseConfig(saved)
363		if f == nil || f.Code != "invalid_config" {
364			t.Fatalf("re-parsing a saved schemeless upstream must fail, got cfg=%+v f=%+v", cfg, f)
365		}
366		if cfg != nil {
367			t.Fatalf("no config may be returned for a rejected document, got %+v", cfg)
368		}
369		if !strings.Contains(f.Reason, `"//***@host.internal/v1"`) {
370			t.Fatalf("reason = %q, want the redacted address", f.Reason)
371		}
372		for _, leaked := range []string{"alice", "pw%4"} {
373			if strings.Contains(f.Reason, leaked) {
374				t.Fatalf("reason = %q leaks %q", f.Reason, leaked)
375			}
376		}
377	
378		// The legal https contract is untouched: credentials and their encoding
379		// survive a save/re-read byte for byte and still resolve.
380		legal := mustConfig(t, `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"https://alice:s3cr%40t@host.internal/v1"}]}`)
381		savedLegal, err := json.Marshal(legal)
382		if err != nil {
383			t.Fatalf("marshal legal: %v", err)
384		}
385		if !strings.Contains(string(savedLegal), `"upstream":"https://alice:s3cr%40t@host.internal/v1"`) {
386			t.Fatalf("legal credentials must survive the save: %s", savedLegal)
387		}
388		reparsed := mustConfig(t, string(savedLegal))
389		res := resolveJSON(t, reparsed, `{"method":"GET","target":"/x"}`)
390		if want := "https://alice:s3cr%40t@host.internal/v1/x"; res.UpstreamURL != want {
391			t.Fatalf("reparsed upstreamURL = %q, want %q", res.UpstreamURL, want)
392		}
393	}
394	
395	// TestSchemelessUpstreamQueryFragmentPrecedence pins the one check that
396	// still precedes address splitting: a "?" or "#" keeps its existing rule,
397	// and that reason never quotes the credential either.
398	func TestSchemelessUpstreamQueryFragmentPrecedence(t *testing.T) {
399		f := assertSchemelessRejected(t, schemelessConfig("//alice:secret@h?q=1"), "",
400			[]string{"alice", "secret"})
401		if !strings.Contains(f.Reason, "must not contain a query string or fragment") {
402			t.Fatalf("reason = %q, want the query/fragment rule", f.Reason)
403		}
404	}
405	
406	// TestRedactUpstreamUserinfoSchemelessDirectly pins the redaction helper on
407	// the schemeless boundary, including the no-userinfo and no-authority
408	// shapes that must stay untouched.
409	func TestRedactUpstreamUserinfoSchemelessDirectly(t *testing.T) {
410		cases := []struct {
411			raw  string
412			want string
413		}{
414			{"//alice:pw%4@api.internal/v1", "//***@api.internal/v1"},
415			{"//alice@host/base", "//***@host/base"},
416			{"//@host/base", "//***@host/base"},
417			{"//host/base", "//host/base"},
418			{"//host/base@x", "//host/base@x"},
419			{"//", "//"},
420			{"api.internal/v1", "api.internal/v1"},
421			{"/abs/path", "/abs/path"},
422			{"https://alice:pw@h/v1", "https://***@h/v1"},
423		}
424		for _, tc := range cases {
425			t.Run(tc.raw, func(t *testing.T) {
426				if got := redactUpstreamUserinfo(tc.raw); got != tc.want {
427					t.Fatalf("redactUpstreamUserinfo(%q) = %q, want %q", tc.raw, got, tc.want)
428				}
429			})
430		}
431	}
