			}
			for _, want := range tc.keep {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want host/path diagnostic %q preserved", f.Reason, want)
				}
			}
			for _, leaked := range tc.hidden {
				if strings.Contains(f.Reason, leaked) {
