1292				upstream: "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b",
1293				target:   "/x",
1294				wantURL:  "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b/x",
1295			},
1296			{
1297				name:     "ipv4 tail and port",
1298				prefix:   "/",
1299				upstream: "http://[::ffff:192.168.0.1]:8080/b",
1300				target:   "/x",
1301				wantURL:  "http://[::ffff:192.168.0.1]:8080/b/x",
1302			},
1303			{
1304				name:     "ordinary domain is unaffected",
1305				prefix:   "/api",
1306				upstream: "http://api.internal/v1",
1307				target:   "/api/x?y=1",
1308				wantURL:  "http://api.internal/v1/x?y=1",
1309			},
