1326				}
1327				if success.UpstreamURL != tc.wantURL {
1328					t.Errorf("upstreamURL = %q, want %q", success.UpstreamURL, tc.wantURL)
1329				}
1330			})
1331		}
1332	}
1333	
1334	// TestResolveCLITargetDirectControlCharacter drives the direct-character
1335	// rule at the command boundary: a JSON-escaped newline decodes to a literal
1336	// control byte in the target, and a space, U+0000..U+001F byte or U+007F
1337	// appearing directly — in the path, a parameter name or a value — makes the
1338	// request invalid_request even when a route would match (or a transform
1339	// would remove the carrying parameter). Percent-encoded forms such as
1340	// "%20" and "%0A" keep resolving. Failure exits non-zero, leaves stdout
1341	// completely empty and emits one JSON error on stderr whose reason names the
1342	// first offending character as U+XXXX; a bad config still wins over such a
1343	// request.
1344	func TestResolveCLITargetDirectControlCharacter(t *testing.T) {
1345		removeConfig := `{
1346		  "routes": [
